test:
company = Node('Company')
a = Node('A', [company])
b = Node('B', [company])
alice = Node('Alice', [a, b])
bob = Node('Bob', [a, b])
carol = Node('Carol', [b])
assert closest_common_groups([alice, bob, carol]) == {b}
